argv:
$ErrorActionPreference='Stop';
$c='E:\WebAIBridge\app\data\supervisor-watchdog.json';
$s='E:\WebAIBridge\app\data\managed-chat-status.json';
$j=Get-Content $c -Raw | ConvertFrom-Json;
$st=$null;if(Test-Path $s){$st=Get-Content $s -Raw | ConvertFrom-Json}
$rows=@();
foreach($m in @($j.managedChats)){
  $status=$null;
  if($st -and $st.chats){$status=$st.chats.PSObject.Properties | Where-Object {$_.Name -eq $m.id} | Select-Object -ExpandProperty Value -First 1}
  $rows += [pscustomobject]@{
    id=$m.id;name=$m.name;role=$m.role;url=$m.url;repository=$m.repository;branch=$m.branch;gitHead=$m.gitHead;
    enabled=$m.enabled;projectId=$m.projectId;
    status=$status.status;lastSeenAt=$status.lastSeenAt;generating=$status.generating;highMode=$status.highMode;
    contextLimit=$status.contextLimit;openTabs=$status.openTabs
  }
}
[pscustomobject]@{rows=$rows;mode=$j.mode;highModeStrategy=$j.highModeStrategy} | ConvertTo-Json -Depth 5 -Compress
